UPDATE /* kh.com.copilot.app.csm.dao.MenuMgtDao.updateMenu */
	   ${schema}.TSCSM0001 
   SET MENU_ENG_NAME       = #{menuEngName}
	 , MENU_URL            = #{menuUrl}
	 , ORDER_SEQ           = #{orderSeq}
	 , APPROVAL_YN         = #{approvalYn}
	 , USE_YN              = #{useYn}
	 , BRANCH_AUTH		   = #{branchAuth}
	 , SYS_CREATE_YMS  = CURRENT_TIMESTAMP
	 , SYS_CREATE_UNO        = #{sysLastUno}
 WHERE OPER_GROUP_CD       = #{operGroupCd}
   AND MENU_ID 			   = #{menuId}
